    "tour.chat-basics.composer.body": "Type a message at the bottom to chat with the agent. Press Enter to send — this creates a real conversation.",
    "tour.chat-basics.perm.title": "Model, agent & permissions",
    "tour.chat-basics.perm.body": "The model button opens the picker where you can switch the model or agent and choose the permission mode: from asking before every operation to full autonomy.",
    "tour.chat-basics.attach.title": "Attachments",
    "tour.chat-basics.attach.body": "The paperclip adds files or images; the agent reads them as context.",
